package app.veyra;
import android.content.*;import org.json.*;import java.util.*;
final class FollowStore {
 static String key(String provider,String kind,String id){return "follow:"+provider+":"+kind+":"+id;}
 static boolean followed(Context c,String provider,String kind,String id){return PersonalStore.prefs(c).contains(key(provider,kind,id));}
 static boolean toggle(Context c,JSONObject detail,String provider,String kind)throws Exception{String key=key(provider,kind,detail.getString("id"));if(PersonalStore.prefs(c).contains(key)){PersonalStore.prefs(c).edit().remove(key).apply();EpisodeMonitor.schedule(c);return false;}int count=detail.getJSONArray("vod_collection").length();if(count<2)throw new IllegalArgumentException("No series episodes are supplied");if(list(c).size()>=20)throw new IllegalArgumentException("Follow up to 20 series per profile");JSONObject title=new JSONObject(detail.toString()).put("_provider",provider).put("_kind",kind);JSONObject record=VelixioData.cleanRecord(title,false).put("audioType",detail.optString("audio_type","0")).put("episodeCount",count).put("notifiedCount",count).put("lastChecked",System.currentTimeMillis());PersonalStore.prefs(c).edit().putString(key,validate(record).toString()).apply();EpisodeMonitor.schedule(c);return true;}
 static LinkedHashMap<String,JSONObject> list(Context c){LinkedHashMap<String,JSONObject> out=new LinkedHashMap<>();List<String> keys=new ArrayList<>(PersonalStore.prefs(c).getAll().keySet());Collections.sort(keys);for(String key:keys)if(key.startsWith("follow:"))try{out.put(key,new JSONObject(PersonalStore.prefs(c).getString(key,"{}")));}catch(Exception ignored){}return out;}
 static JSONObject validate(JSONObject raw)throws Exception{JSONObject out=VelixioData.cleanRecord(raw,false);String type=raw.getString("audioType");int count=raw.getInt("episodeCount"),notified=raw.getInt("notifiedCount");long checked=raw.getLong("lastChecked");if(type.length()>32||count<0||count>100000||notified<0||notified>count||checked<0||checked>4102444800000L)throw new Exception("Invalid followed series");return out.put("audioType",type).put("episodeCount",count).put("notifiedCount",notified).put("lastChecked",checked);}
 static int nextCount(int known,int received){return Math.max(known,Math.max(0,Math.min(100000,received)));}
}
